package erpmetrics

import "strconv"

type SceneMetric struct { Label string `json:"label"`; Value string `json:"value"` }
type BlueprintAssemblySpec struct {
 ID string `json:"id"`; PartNumber string `json:"partNumber"`; TitleEN string `json:"titleEn"`; LineTH string `json:"lineTh"`
 AssembledPosition [3]float64 `json:"assembledPosition"`; ExplodedOffset [3]float64 `json:"explodedOffset"`; Size [3]float64 `json:"size"`
 Metrics []SceneMetric `json:"metrics"`; CodeRuleEN string `json:"codeRuleEn"`; CodeRuleTH string `json:"codeRuleTh"`; CodeRefs []string `json:"codeRefs"`
}
type BlueprintTokenWaypoint struct { Step string `json:"step"`; LabelEN string `json:"labelEn"`; LabelTH string `json:"labelTh"`; AssemblyID string `json:"assemblyId"`; Position [3]float64 `json:"position"` }
type BlueprintSheetSpec struct { SheetNumber int `json:"sheetNumber"`; TotalSheets int `json:"totalSheets"`; Code string `json:"code"`; TitleEN string `json:"titleEn"`; SubtitleTH string `json:"subtitleTh"`; ExplodeFactor float64 `json:"explodeFactor"`; CameraTarget [3]float64 `json:"cameraTarget"`; CameraPosition [3]float64 `json:"cameraPosition"`; CameraZoom float64 `json:"cameraZoom"` }
type BlueprintTitleBlock struct { DrawingTitle string `json:"drawingTitle"`; DrawingCode string `json:"drawingCode"`; Scale string `json:"scale"`; Projection string `json:"projection"`; TotalSheets int `json:"totalSheets"` }
type BlueprintSceneModel struct { TitleBlock BlueprintTitleBlock `json:"titleBlock"`; OrgRole string `json:"orgRole"`; Assemblies []BlueprintAssemblySpec `json:"assemblies"`; TokenPath []BlueprintTokenWaypoint `json:"tokenPath"`; Sheets []BlueprintSheetSpec `json:"sheets"` }
func nullableCount(value *int64)string{if value==nil{return "Owner/admin only"};return strconv.FormatInt(*value,10)}
